  readonly reference: string;
  readonly settledCents: number;
}

export interface PaymentGateway {
  charge(accountId: string, cents: number): Promise<ChargeReceipt>;
}

export async function collectInvoice(gateway: PaymentGateway, accountId: string, cents: number): Promise<ChargeReceipt> {
  if (cents <= 0) throw new RangeError("cents must be positive");
  return gateway.charge(accountId, cents);
}

