export function StreamingTail({ stream }: { readonly stream: ReadableStream<string> }) {
  const [draft, setDraft] = useState("");
  const bufferRef = useRef("");
  const frameRef = useRef(0);

  useEffect(() => {
    let cancelled = false;
    const reader = stream.getReader();
    void (async () => {
      while (!cancelled) {
        const { done, value } = await reader.read();
        if (done) break;
        bufferRef.current += value;
        if (!frameRef.current) {
          frameRef.current = requestAnimationFrame(() => {
            frameRef.current = 0;
            setDraft(bufferRef.current);
          });
        }
      }
    })();
    return () => {
      cancelled = true;
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
      void reader.cancel();
    };
  }, [stream]);

  const draftHtml = useMemo(() => String(marked.parse(draft)), [draft]);
  return <div dangerouslySetInnerHTML={{ __html: draftHtml }} />;
}

