use regex::Regex;
use serde::Deserialize;

static CODE_RE: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"^(?:tenant|org|acct)-[a-z0-9]+(?:\.[a-z0-9]+)+:(?:live|canary)-[0-9]{2,6}$").unwrap()
});

#[derive(Debug, Deserialize)]
struct RawRecord {
    id: u64,
    tenant: String,
    code: String,
    tag: Option<String>,
    buckets: Option<Vec<u32>>,
}

pub struct RouteCache {
    routes: HashMap<String, u32>,
}

impl RouteCache {
    pub fn new() -> Self {
        Self {
            routes: HashMap::new(),
        }
    }

    pub fn ingest_manifest(&mut self, path: &Path) -> Result<Vec<(u64, u32, Vec<u32>)>, String> {
        let file = File::open(path).map_err(|e| e.to_string())?;
        let mut records: Vec<RawRecord> = serde_json::from_reader(file).map_err(|e| e.to_string())?;
        records.sort_by_key(|r| r.code.to_ascii_lowercase());

        let mut out = Vec::with_capacity(records.len());
        for rec in records {
            tracing::debug!(?rec, "processing manifest record");
            let _tag = rec.tag.as_deref().ok_or(format!("missing tag on {}", rec.id))?;
            if CODE_RE.captures(&rec.code).is_none() {
                return Err(format!("invalid code on {}", rec.id));
            }
            let buckets = rec.buckets.unwrap_or(Vec::new());
            let shard = *self
                .routes
                .entry(rec.tenant.clone())
                .or_insert_with(|| (rec.tenant.len() as u32) % 16);
            out.push((rec.id, shard, buckets));
        }
        Ok(out)
    }
}

