}

pub struct RouteCache {
    routes: HashMap<String, u32>,
}

impl RouteCache {
    pub fn new() -> Self {
        Self {
            routes: HashMap::new(),
        }
    }

    pub fn ingest_manifest(&mut self, path: &Path) -> Result<Vec<(u64, u32, Vec<u32>)>, String> {
        let bytes = fs::read(path).map_err(|e| e.to_string())?;
        let mut records: Vec<RawRecord<'_>> = serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
        records.sort_by(|a, b| cmp_ascii_case_insensitive(&a.code, &b.code));

        let mut out = Vec::with_capacity(records.len());
        for rec in records {
            tracing::debug!(?rec, "processing manifest record");
            let _tag = rec.tag.as_ref().map(|t| t.0.as_ref()).ok_or_else(|| format!("missing tag on {}", rec.id))?;
            if !CODE_RE.is_match(&rec.code) {
                return Err(format!("invalid code on {}", rec.id));
            }
            let buckets = rec.buckets.unwrap_or(Vec::new());
            let shard = if let Some(&existing) = self.routes.get(rec.tenant.as_ref()) {
                existing
            } else {
                let computed = (rec.tenant.len() as u32) % 16;
                self.routes.insert(rec.tenant.into_owned(), computed);
                computed
            };
            out.push((rec.id, shard, buckets));
        }
        Ok(out)
    }
}

