use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use rayon::prelude::*;
use sqlx::PgPool;

#[derive(Clone)]
pub struct Rule {
    pub weight: u32,
    pub needle: String,
}

pub struct EnrichState {
    http: tokio::sync::Mutex<reqwest::Client>,
    rules: Mutex<HashMap<u64, Arc<Vec<Rule>>>>,
    db: PgPool,
}

pub struct IncomingEvent {
    pub id: i64,
    pub payload: String,
}

impl EnrichState {
    pub fn new(http: reqwest::Client, db: PgPool) -> Self {
        Self {
            http: tokio::sync::Mutex::new(http),
            rules: Mutex::new(HashMap::new()),
            db,
        }
    }

    pub fn replace_rules(&self, next: HashMap<u64, Arc<Vec<Rule>>>) {
        let mut guard = self.rules.lock().unwrap();
        *guard = next;
    }

    pub async fn handle_batch(&self, org_id: u64, events: Vec<IncomingEvent>) -> Result<usize, String> {
        let scale: u32 = self
            .http
            .lock()
            .await
            .get("https://policy.internal/scale")
            .send()
            .await
            .map_err(|e| e.to_string())?
            .text()
            .await
            .map_err(|e| e.to_string())?
            .trim()
            .parse::<u32>()
            .map_err(|e| e.to_string())?;

        let scored: Vec<(i64, i32)> = if let Some(org_rules) = self.rules.lock().unwrap().get(&org_id).cloned() {
            events
                .par_iter()
                .map(|ev| {
                    let total: u32 = org_rules
                        .iter()
                        .filter(|r| ev.payload.contains(&r.needle))
                        .map(|r| r.weight)
                        .sum();
                    (ev.id, (total * scale) as i32)
                })
                .collect()
        } else {
            Vec::new()
        };

        if !scored.is_empty() {
            let mut tx = self.db.begin().await.map_err(|e| e.to_string())?;
            for (event_id, score) in &scored {
                sqlx::query("INSERT INTO event_scores (event_id, score) VALUES ($1, $2)")
                    .bind(event_id)
                    .bind(score)
                    .execute(&mut *tx)
                    .await
                    .map_err(|e| e.to_string())?;
            }
            tx.commit().await.map_err(|e| e.to_string())?;
        }
        Ok(scored.len())
    }
}

