use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use rayon::prelude::*;
use sqlx::PgPool;

#[derive(Clone)]
pub struct Rule {
    pub weight: u32,
    pub needle: String,
}

pub struct EnrichState {
    http: reqwest::Client,
    rules: RwLock<HashMap<u64, Arc<Vec<Rule>>>>,
    db: PgPool,
}

pub struct IncomingEvent {
    pub id: i64,
    pub payload: String,
}

impl EnrichState {
    pub fn new(http: reqwest::Client, db: PgPool) -> Self {
        Self {
            http,
            rules: RwLock::new(HashMap::new()),
            db,
        }
    }

    pub fn replace_rules(&self, next: HashMap<u64, Arc<Vec<Rule>>>) {
        let old = {
            let mut guard = self.rules.write().unwrap();
            std::mem::replace(&mut *guard, next)
        };
        drop(old);
    }

    pub async fn handle_batch(&self, org_id: u64, events: Vec<IncomingEvent>) -> Result<usize, String> {
        let scale: u32 = self
            .http
            .get("https://policy.internal/scale")
            .send()
            .await
            .map_err(|e| e.to_string())?
            .text()
            .await
            .map_err(|e| e.to_string())?
            .trim()
            .parse::<u32>()
            .map_err(|e| e.to_string())?;

        let org_rules = self.rules.read().unwrap().get(&org_id).cloned();
        let (event_ids, scores): (Vec<i64>, Vec<i32>) = if let Some(org_rules) = org_rules {
            let (tx, rx) = tokio::sync::oneshot::channel();
            rayon::spawn(move || {
                let res = events
                    .par_iter()
                    .map(|ev| {
                        let total: u32 = org_rules
                            .iter()
                            .filter(|r| ev.payload.contains(&r.needle))
                            .map(|r| r.weight)
                            .sum();
                        (ev.id, (total * scale) as i32)
                    })
                    .unzip();
                let _ = tx.send(res);
            });
            rx.await.map_err(|e| e.to_string())?
        } else {
            (Vec::new(), Vec::new())
        };

        if !event_ids.is_empty() {
            sqlx::query("INSERT INTO event_scores (event_id, score) SELECT * FROM UNNEST($1::bigint[], $2::int4[])")
                .bind(&event_ids)
                .bind(&scores)
                .execute(&self.db)
                .await
                .map_err(|e| e.to_string())?;
        }
        Ok(event_ids.len())
    }
}
